target_output:
Below is a C++ program that reads a CSV file and converts it into a JSON file. The program assumes the first row of the CSV file contains headers, which will be used as keys in the JSON output.

```cpp
#include <iostream>
#include <fstream>
#include <sstream>
#include <vector>
#include <string>
#include <json/json.h> // Requires jsoncpp library

// Function to split a string by a delimiter
std::vector<std::string> split(const std::string &str, char delimiter) {
    std::vector<std::string> tokens;
    std::stringstream ss(str);
    std::string token;
    while (std::getline(ss, token, delimiter)) {
        tokens.push_back(token);
    }
    return tokens;
}

// Function to convert CSV to JSON
void csvToJson(const std::string &csvFilename, const std::string &jsonFilename) {
    std::ifstream csvFile(csvFilename);
    if (!csvFile.is_open()) {
        std::cerr << "Error: Unable to open CSV file." << std::endl;
        return;
    }

    Json::Value jsonRoot;
    std::string line, headerLine;
    std::vector<std::string> headers;

    // Read the header line
    if (std::getline(csvFile, headerLine)) {
        headers = split(headerLine, ',');
    } else {
        std::cerr << "Error: CSV file is empty." << std::endl;
        return;
    }

    // Read the rest of the CSV file
    int lineNumber = 0;
    while (std::getline(csvFile, line)) {
        lineNumber++;
        std::vector<std::string> row = split(line, ',');
        if (row.size() != headers.size()) {
            std::cerr << "Warning: Skipping line " << lineNumber << " due to mismatched columns." << std::endl;
            continue;
        }

        Json::Value jsonRow;
        for (size_t i = 0; i < headers.size(); ++i) {
            jsonRow[headers[i]] = row[i];
        }
        jsonRoot.append(jsonRow);
    }

    csvFile.close();

    // Write JSON to file
    Json::StreamWriterBuilder writer;
    std::unique_ptr<Json::StreamWriter> jsonWriter(writer.newStreamWriter());
    std::ofstream jsonFile(jsonFilename);
    if (!jsonFile.is_open()) {
        std::cerr << "Error: Unable to open JSON file for writing." << std::endl;
        return;
    }

    jsonWriter->write(jsonRoot, &jsonFile);
    jsonFile.close();

    std::cout << "CSV file successfully converted to JSON." << std::endl;
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        std::cerr << "Usage: " << argv[0] << " <input.csv> <output.json>" << std::endl;
        return 1;
    }

    csvToJson(argv[1], argv[2]);
    return 0;
}
```

### Prerequisites:
1. **jsoncpp Library**: Install the `jsoncpp` library for JSON handling. On Ubuntu, you can install it using:
   ```bash
   sudo apt-get install libjsoncpp-dev
   ```

2. **Compilation**: Compile the program with the following command:
   ```bash
   g++ -o csv_to_json csv_to_json.cpp -ljsoncpp
   ```

### Usage:
Run the program with the input CSV file and desired output JSON file as arguments:
```bash
./csv_to_json input.csv output.json
```

### Example CSV (`input.csv`):
```csv
name,age,occupation
John Doe,30,Engineer
Jane Smith,25,Doctor
```

### Output JSON (`output.json`):
```json
[
    {
        "name": "John Doe",
        "age": "30",
        "occupation": "Engineer"
    },
    {
        "name": "Jane Smith",
        "age": "25",
        "occupation": "Doctor"
    }
]
```

This program assumes the CSV file is well-formed and does not handle quoted fields with commas. For more robust CSV parsing, consider using a library like [RapidCSV](https://github.com/d99kris/rapidcsv).
